   ════════════════════════════════════════════════════════ */

/* ─────────────────────────────
   DESIGN TOKENS
   ───────────────────────────── */
.page-header {
    --c-bg: rgba(2, 10, 67, 0.90);
    --c-bg-deep: rgba(5, 20, 50, 0.95);

    --c-accent: #06F5FF;
    --c-accent-glow: rgba(6, 245, 255, 0.15);
    --c-accent-border: rgba(6, 245, 255, 0.30);

    --c-active: #1E4AE9;
    --c-active-end: #1636b0;
    --c-active-glow: rgba(30, 74, 233, 0.50);

    --c-text: #FFFFFF;
    --c-text-dim: #CADADD;
    --c-text-muted: #90A4AE;

    --radius-tab: 0.35em;
    --transition: 0.3s cubic-bezier(0.4, 0.0, 0.2, 1);
}

/* ─────────────────────────────
   ROOT CONTAINER
   ───────────────────────────── */
.page-header,
.page-header * {
    box-sizing: border-box;
}

.page-header {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    height: 100%;
    margin: 0;

    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: stretch;

    background: linear-gradient(180deg, var(--c-bg) 0%, var(--c-bg-deep) 100%);
    padding: 0.3em 0.8em;
    font-family: 'Roboto', Arial, sans-serif;
    color: var(--c-text);
    overflow: hidden;
}

/* ─────────────────────────────
   TOP ROW: Title + Clock
   ───────────────────────────── */
.header-top {
    flex: 0 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.15em 0.2em;
    min-height: 0;
}

.title-section {
    font-size: 1.1em;
    font-weight: 900;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    flex: 1;
    min-width: 0;
    color: var(--c-text);
    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
}

.time-section {
    display: flex;
    align-items: baseline;
    gap: 0.4em;
    font-size: 0.75em;
    font-weight: 700;
    letter-spacing: 0.03em;
    white-space: nowrap;
    flex-shrink: 0;
    margin-left: 1em;
    color: var(--c-text);
}

.separator {
    opacity: 0.5;
}

.timezone {
    font-size: 0.85em;
    opacity: 0.5;
    font-weight: 500;
}

/* ─────────────────────────────
   DIVIDER
   ───────────────────────────── */
.header-divider {
    flex: 0 0 auto;
    height: 1px;
    margin: 0.2em 0;
    background: linear-gradient(
        90deg,
        transparent 0%,
        var(--c-accent-border) 20%,
        var(--c-accent-border) 80%,
        transparent 100%
    );
    opacity: 0.6;
}

/* ─────────────────────────────
   BOTTOM ROW: Navigation Tabs
   ───────────────────────────── */
.header-nav {
    flex: 1 1 auto;
    display: flex;
    justify-content: center;
    align-items: stretch;
    gap: 0.3em;
    padding: 0.1em 0;
    min-height: 0;
}

/* ─── Individual Tab ─── */
.nav-item {
    color: var(--c-text-dim);
    font-size: 0.78em;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    white-space: nowrap;

    cursor: pointer;
    padding: 0.4em 0.8em;
    border-radius: var(--radius-tab);
    border: 1px solid transparent;
    opacity: 0.75;

    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;

    position: relative;
    user-select: none;
    -webkit-user-select: none;
    transition: all var(--transition);
}

/* ─── Hover ─── */
.nav-item:hover {
    opacity: 1;
    color: var(--c-text);
    background-color: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.12);
    transform: translateY(-1px);
}

/* ─── Active State ─── */
.nav-item.active {
    color: var(--c-text) !important;
    background: linear-gradient(135deg, var(--c-active) 0%, var(--c-active-end) 100%);
    opacity: 1 !important;
    box-shadow: 0 0.2em 0.8em var(--c-active-glow);
    border-color: rgba(255, 255, 255, 0.15);
    transform: translateY(0);
}

/* Cyan bottom accent line on active tab */
.nav-item.active::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 15%;
    right: 15%;
    height: 2px;
    background: var(--c-accent);
    border-radius: 1px;
    box-shadow: 0 0 6px var(--c-accent-glow);
}

