    font-size: 0.78em;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    white-space: nowrap;

    cursor: pointer;
    padding: 0.4em 0.8em;
    border-radius: var(--radius-tab);
    border: 1px solid transparent;
    opacity: 0.75;

    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;

    position: relative;
    user-select: none;
    -webkit-user-select: none;
    transition: all var(--transition);
}

/* ─── Hover ─── */
.nav-item:hover {
    opacity: 1;
    color: var(--c-text);
    background-color: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.12);
    transform: translateY(-1px);
}

/* ─── Active State ─── */
.nav-item.active {
    color: var(--c-text) !important;
    background: linear-gradient(135deg, var(--c-active) 0%, var(--c-active-end) 100%);
    opacity: 1 !important;
    box-shadow: 0 0.2em 0.8em var(--c-active-glow);
    border-color: rgba(255, 255, 255, 0.15);
    transform: translateY(0);
}

/* Cyan bottom accent line on active tab */
.nav-item.active::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 15%;
    right: 15%;
    height: 2px;
    background: var(--c-accent);
    border-radius: 1px;
    box-shadow: 0 0 6px var(--c-accent-glow);
}

settings.nodeRelationQueryFunction:
var entity = nodeCtx.entity;
  var query = {
      parameters: {
          rootId: entity.id.id,
          rootType: entity.id.entityType,
          direction: "FROM",
          maxLevel: 1
      },
      filters: [{
          relationType: "Contains",
          entityTypes: []
      }]
  };
  return query;

settings.nodeHasChildrenFunction:
/**

// Function should return boolean value indicating whether current node has children (whether it can be expanded).

// The following example code will restrict entities hierarchy expansion up to third level.

return nodeCtx.level <= 2;

// The next example code will restrict entities expansion according to the value of example 'nodeHasChildren' attribute.

var data = nodeCtx.data;
if (data.hasOwnProperty('nodeHasChildren') && data['nodeHasChildren'] !== null) {
    return data['nodeHasChildren'] === 'true';
} else {
    return true;
}

**/

settings.nodeOpenedFunction:
var entity = nodeCtx.entity;

// Use the ID of your default device (find this from the ThingsBoard entity list)
var defaultDeviceId = '783e5900-45af-11ef-b4ce-d5aee9e495ad';

// Check if the current entity matches the default device and open it
if (entity.id.id === defaultDeviceId) {
    return true; // Open this device by default
} else {
    return nodeCtx.level <= 3; // Default behavior for other nodes (first level nodes open)
}

settings.nodeDisabledFunction:
var data = nodeCtx.data;
var excludedDevices = ['VPE Plant1', 'VPE Plant2', 'VPE Plant1_Block1','VPE Plant1_Block2', 'VPE Plant2_Block1','VPE Plant2_Block2', 'VPE P1_EnergyMeter', 'VPE P2_EnergyMeter', 'VPE P1_WSTN','VPE P2_WSTN'];
if (excludedDevices.includes(nodeCtx.entity.name)) {
    return true; // Disable these devices from being selectable
} else {
    return false;
}

settings.nodeIconFunction:
var entity = nodeCtx.entity;
var type = entity.id.entityType;
if (type === 'DEVICE') return { materialIcon: 'fiber_manual_record' };
if (type === 'ASSET')  return { materialIcon: 'fiber_manual_record' };
return { materialIcon: 'fiber_manual_record' };

settings.nodeTextFunction:
/**

// Function should return text (can be HTML code) for the current node.

// The following example code will generate node text consisting of entity name and temperature if temperature value is present in entity attributes/timeseries.

var data =  nodeCtx.data;
var entity = nodeCtx.entity;
var text = entity.name;
if (data.hasOwnProperty('temperature') && data['temperature'] !== null) {
    text += " <b>"+ data['temperature'] +" °C</b>";
}
return text;

**/

settings.nodesSortFunction:
/**

// This function is used to sort nodes of the same level. Function should compare two nodes and return 
// integer value: 
//     - less than 0 - sort nodeCtx1 to an index lower than nodeCtx2
//     - 0 - leave nodeCtx1 and nodeCtx2 unchanged with respect to each other
//     - greater than 0 - sort nodeCtx2 to an index lower than nodeCtx1

// The following example code will sort entities first by entity type in alphabetical order then
// by entity name in alphabetical order.

var result = nodeCtx1.entity.id.entityType.localeCompare(nodeCtx2.entity.id.entityType);
if (result === 0) {
    result = nodeCtx1.entity.name.localeCompare(nodeCtx2.entity.name);
}
return result;

**/
